type WorkspaceKey =
  | "floor" | "radar" | "qualification" | "funders" | "doctrine" | "cases" | "data-room" | "pipeline"
  | "coordinator" | "ai-command" | "strategy" | "simulator" | "reports" | "manual" | "approvals" | "settings" | "production";

type ModalKey =
  | "command" | "opportunity" | "source" | "qualification" | "funder" | "objection" | "doctrine" | "case"
  | "section" | "upload" | "package" | "stage" | "submission" | "mission" | "email" | "call"
  | "approval" | "ai-run" | "ai-issue" | "scenario" | "stress" | "report" | "blocker" | "flag" | null;

type Entity = {
  id: string;
  eyebrow: string;
  title: string;
  status: string;
  risk: string;
  owner: string;
  deadline: string;
  summary: string;
  proof: string;
  approval: string;
  next: string;
};

type Workspace = {
  key: WorkspaceKey;
  href: string;
  label: string;
  floor: string;
  metaphor: string;
  hero: string;
  copy: string;
  surface: string;
  status: string;
  count: number;
  api: string;
  primary: ModalKey;
  secondary: ModalKey;
  kpis: Array<{ label: string; value: string; note: string; tone: string }>;
  intelligence: string[];
  features: string[];
  entities: Entity[];
};

function makeEntity(id: string, eyebrow: string, title: string, status: string, risk: string, summary: string, next: string): Entity {
  return {
    id, eyebrow, title, status, risk,
    owner: risk.includes("Founder") || risk.includes("Financial") ? "Founder / Managing Director" : "Capital Command Team",
    deadline: risk.includes("Critical") ? "48h" : "This cycle",
    summary,
    proof: "Proof, source, version or operational evidence must be attached before external execution.",
    approval: risk.includes("Low") || risk.includes("Medium") ? "Human review" : "Founder approval required",
    next,
  };
}

