function getWorkspace(key: WorkspaceKey): Workspace {
  return workspaces.find((workspace) => workspace.key === key) || workspaces[0];
}

function tone(value: string) {
  const v = value.toLowerCase();
  if (v.includes("red") || v.includes("blocked") || v.includes("approval") || v.includes("disabled") || v.includes("financial") || v.includes("founder")) return "border-rose-200 bg-rose-50 text-rose-800";
  if (v.includes("amber") || v.includes("needs") || v.includes("proof") || v.includes("storage")) return "border-amber-200 bg-amber-50 text-amber-800";
  if (v.includes("green") || v.includes("live") || v.includes("ready") || v.includes("active")) return "border-emerald-200 bg-emerald-50 text-emerald-800";
  if (v.includes("purple") || v.includes("ai") || v.includes("provider")) return "border-indigo-200 bg-indigo-50 text-indigo-800";
  return "border-blue-200 bg-blue-50 text-blue-800";
}

function Badge({ children, value }: { children: ReactNode; value?: string }) {
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.16em] ${tone(value || String(children))}`}>{children}</span>;
}

