function SectionTitle({ eyebrow, title, copy }: { eyebrow: string; title: string; copy: string }) {
  return <div className="mb-5"><p className="text-[11px] font-black uppercase tracking-[.28em] text-blue-700">{eyebrow}</p><h3 className="mt-1 text-2xl font-black tracking-[-.035em]">{title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{copy}</p></div>;
}

function CapitalFlowMap({ selected, onSelect, onDrawer }: { selected: WorkspaceKey; onSelect: (key: WorkspaceKey) => void; onDrawer: () => void }) {
  return <section className="rounded-[2rem] border border-slate-200 bg-white/90 p-6 shadow-xl shadow-blue-950/5"><SectionTitle eyebrow="Capital Flow Map" title="Radar → Qualification → Funder → Strategy → Case → Data Room → Pipeline → Coordinator → Reports → Learning" copy="The mandatory wow surface. Every node is clickable and opens a controlled workspace context." /><div className="grid grid-cols-5 gap-3 max-xl:grid-cols-2 max-md:grid-cols-1">{flow.map(([key,label,status,count], index) => <button key={key} onClick={() => onSelect(key as WorkspaceKey)} className={`relative min-h-36 rounded-[1.7rem] border p-4 text-left transition hover:-translate-y-1 hover:shadow-xl ${selected === key ? "border-blue-400 bg-blue-50 shadow-xl shadow-blue-950/10" : "border-blue-100 bg-gradient-to-br from-white to-blue-50"}`}><em className="not-italic text-sm font-black text-blue-300">{String(index+1).padStart(2,"0")}</em><strong className="mt-5 block text-lg">{label}</strong><span className="mt-1 block text-xs text-slate-500">{status}</span><b className="absolute bottom-3 right-4 text-3xl text-blue-700">{count}</b></button>)}</div><div className="mt-5 flex flex-wrap gap-3"><button onClick={onDrawer} className="rounded-full bg-blue-950 px-5 py-3 text-sm font-black text-white">Open selected drawer</button><a href={`/ac-capital-os/${selected}`} className="rounded-full border border-blue-200 bg-white px-5 py-3 text-sm font-black text-blue-900 no-underline">Enter workspace</a></div></section>;
}

