function CapitalModal({ modal, workspace, close }: { modal: Exclude<ModalKey, null>; workspace: Workspace; close: () => void }) {
  const copy = modalText[modal];
  return <div className="fixed inset-0 z-50 bg-slate-950/30 backdrop-blur-xl" onClick={close}><section className="absolute left-1/2 top-1/2 max-h-[calc(100vh-2rem)] w-[min(940px,calc(100vw-2rem))] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-[2rem] bg-white p-6 shadow-2xl" onClick={(e)=>e.stopPropagation()}><div className="flex justify-between gap-4"><div><Badge>Premium Modal</Badge><h3 className="mt-4 text-3xl font-black tracking-[-.04em]">{copy.title}</h3><p className="mt-2 text-slate-600">{copy.purpose}</p></div><button onClick={close} className="h-11 w-11 rounded-2xl border border-slate-200 bg-slate-50 text-2xl">×</button></div>{modal === "command" ? <div className="mt-5 grid grid-cols-2 gap-3 max-md:grid-cols-1">{commandActions.map((a)=><button key={a.label} className="rounded-3xl border border-slate-200 bg-white p-4 text-left hover:shadow-xl"><strong>{a.label}</strong><small className="mt-2 block text-slate-500">{a.desc}</small></button>)}</div> : <div className="mt-5 grid grid-cols-[1.25fr_.75fr] gap-4 max-lg:grid-cols-1"><div className="grid grid-cols-2 gap-3 max-md:grid-cols-1">{copy.fields.map((field)=><label key={field} className="grid gap-1"><span className="text-[11px] font-black uppercase tracking-[.16em] text-slate-500">{field}</span><input className="rounded-2xl border border-slate-200 px-3 py-3" placeholder={`${field} · ${workspace.label}`} /></label>)}</div><div className="rounded-3xl border border-amber-200 bg-amber-50 p-4 text-amber-900"><h4 className="font-black">Risk / approval / proof boundary</h4><p className="mt-2 text-sm leading-6">{copy.safety}</p><p className="mt-2 text-sm leading-6">Expected result: safe draft/action record, audit note, no hidden automation.</p><p className="mt-2 text-sm leading-6">Failure state: disabled with reason, missing proof, missing approval, storage not configured, or AI dry-run only.</p></div></div>}<footer className="mt-5 flex justify-end gap-3"><button onClick={close} className="rounded-full border border-slate-200 bg-white px-5 py-3 text-sm font-black">Cancel</button><button onClick={close} className="rounded-full bg-blue-950 px-5 py-3 text-sm font-black text-white">{copy.action}</button></footer></section></div>;
}
